def tr_lower(s: str) -> str:
    """Türkçe kurallarına göre metni küçük harfe çevirir."""
    mapping = {
        'İ': 'i',
        'I': 'ı',
        'Ş': 'ş',
        'Ğ': 'ğ',
        'Ü': 'ü',
        'Ö': 'ö',
        'Ç': 'ç'
    }
    # Not: Standart .lower() zaten çoğu şeyi yapar ama İ ve I kritik.
    # Ancak en güvenli yol karakter bazlı veya replace ile gitmektir.
    res = []
    for char in s:
        if char == 'İ':
            res.append('i')
        elif char == 'I':
            res.append('ı')
        else:
            res.append(char.lower())
    return "".join(res)

def tr_upper(s: str) -> str:
    """Türkçe kurallarına göre metni büyük harfe çevirir."""
    res = []
    for char in s:
        if char == 'i':
            res.append('İ')
        elif char == 'ı':
            res.append('I')
        else:
            res.append(char.upper())
    return "".join(res)

def tr_sorted(words: list[str]) -> list[str]:
    """Kelimeleri Türkçe alfabesine göre sıralar."""
    # Türk alfabesi sırası (küçük harf üzerinden)
    # Karakterler: 0123456789abcçdefgğhıijklmnoöpqrsştuüvwxyz
    # Not: İ harfi alfabetik olarak I'dan sonra gelir ancak küçük harf hali 'i'dir.
    # İnceleme: a b c ç d e f g ğ h ı i j k l m n o ö p r s ş t u ü v y z
    # Soruda verilen sıralama: abcçdefgğhıijklmnoöpqrsştuüvwxyz
    # Dikkat: Soruda verilen listede 'i' harfi 'ı' harfinden sonra gelmiş. 
    # Normal Türk alfabesi: ... g, ğ, h, ı, i, j ... şeklindedir.
    # Verilen özel sıralama: ... g, ğ, h, ı, i, j ... (aslında standart ile aynı gibi duruyor)

    tr_alphabet = "abcçdefgğhıijklmnoöpqrsştuüvwxyz"
    # Karakterlerin sıralama değerlerini belirleyelim
    # Diğer karakterler (sayı, boşluk, noktalama) en başta olmalı.
    # Onlar için Unicode değeri kullanılacak ama alfabetik karakterlerden küçük olmalı.

    char_order = {char: i for i, char in enumerate(tr_alphabet)}

    def get_sort_key(word: str):
        key = []
        for char in word:
            lower_char = tr_lower(char)
            if lower_char in char_order:
                # Alfabetik bir karakter ise sırasını ver
                # Diğer karakterlerden (Unicode 0-47 vb.) daha büyük bir değer verilmeli
                # Ancak soru "listedeki olmayan karakterler en önce gelir" diyor.
                # Bu durumda alfabetik karakterlere yüksek bir offset verelim.
                key.append(1000 + char_order[lower_char])
            else:
                # Liste dışı karakter (sayı, boşluk vb.)
                # Unicode değerini kullan ama alfabetik karakterlerden küçük olsun.
                key.append(ord(lower_char))
        return key

    # Python'un sorted() fonksiyonu stabil (stable) bir sıralama algoritması kullanır (Timsort).
    # Bu sayede eşit sayılan kelimeler (key bazında) orijinal sıralarını korur.
    return sorted(words, key=get_sort_key)

